  $('classification-import-review')?.addEventListener('click',()=>{if(!pendingClassificationPlan)return;const panel=$('classification-import-change-details'),button=$('classification-import-review');if(!panel||!button)return;const open=panel.hidden;panel.hidden=!open;button.setAttribute('aria-expanded',String(open));button.textContent=open?'Hide Changes':`Review Changes · ${pendingClassificationPlan.items.filter(item=>item.kind!=='same').length}`;if(open)panel.scrollIntoView({behavior:'smooth',block:'nearest'});});
  $('classification-import-clear')?.addEventListener('click',()=>{clearClassificationPreview();showClassificationStatus('Classification merge preview cleared.');});
  $('classification-import-continue')?.addEventListener('click',async()=>{const plan=pendingClassificationPlan;if(!plan)return;const resolutions=classificationResolutions();const incomingConflictCount=plan.items.filter(item=>item.kind==='conflict'&&resolutions[item.id]==='incoming').length;const actionable=plan.counts.new+plan.counts.incomingNewer+incomingConflictCount;if(!actionable){showClassificationStatus('Nothing is selected to change on this browser. Newer local copies and unresolved conflicts remain untouched.');return;}if(!(await askClassificationMerge(plan,resolutions)))return;try{const result=window.WLPClassificationMetadata.applyPortableMerge(plan,resolutions);syncSummary();showClassificationStatus(`Classification merge complete · ${result.added} new · ${result.updated} newer · ${result.conflictIncoming} conflict${result.conflictIncoming===1?'':'s'} resolved to incoming · ${result.conflictLocal} conflict${result.conflictLocal===1?'':'s'} kept local.`);clearClassificationPreview();}catch(error){console.error('Classification merge failed:',error);showClassificationStatus(error?.message||String(error),true);}});
